let releaseChromeCollisionRAF=0;
function updateReleaseChromeCollision(){
  releaseChromeCollisionRAF=0;
  const chrome=releaseDialogInner?.querySelector('.releaseChrome');
  const heading=releaseDetail?.querySelector('.detailHeading');
  if(!chrome||!heading||!releaseDialog.open){
    chrome?.classList.remove('titleCollision','collisionPending');
    return
  }
  const chromeRect=chrome.getBoundingClientRect();
  const nodes=[heading.querySelector('.eyebrow'),heading.querySelector('h1')].filter(Boolean);
  let collision=false;
  for(const node of nodes){
    const range=document.createRange();
    range.selectNodeContents(node);
    for(const r of range.getClientRects()){
      if(r.width<=0||r.height<=0)continue;
      if(r.right>chromeRect.left-8&&r.left<chromeRect.right+4&&r.bottom>chromeRect.top-4&&r.top<chromeRect.bottom+4){collision=true;break}
    }
    range.detach?.();
    if(collision)break
  }
  chrome.classList.toggle('titleCollision',collision);
  chrome.classList.remove('collisionPending')
}
function queueReleaseChromeCollision(){
  cancelAnimationFrame(releaseChromeCollisionRAF);
  releaseChromeCollisionRAF=requestAnimationFrame(()=>requestAnimationFrame(updateReleaseChromeCollision))
}
window.addEventListener('resize',queueReleaseChromeCollision,{passive:true});
document.addEventListener('fullscreenchange',queueReleaseChromeCollision);

// Release chrome is pointer-enter driven, not CSS :hover driven. This matters
// when Previous/Next is clicked: the mouse remains over the same top-right
// hotspot after navigation, but the controls should hide until the pointer
// actually leaves and re-enters that hotspot.
let releaseChromePointerKnown=false,releaseChromePointerX=0,releaseChromePointerY=0,releaseChromeHoverSuppressed=false;
document.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;releaseChromePointerKnown=true;releaseChromePointerX=e.clientX;releaseChromePointerY=e.clientY},{passive:true});
function releaseChromePointerInside(chrome){
  if(!chrome||!releaseChromePointerKnown)return false;
  const r=chrome.getBoundingClientRect();
  return releaseChromePointerX>=r.left&&releaseChromePointerX<=r.right&&releaseChromePointerY>=r.top&&releaseChromePointerY<=r.bottom
}
function resetReleaseChromePointerVisibility(){
  const chrome=releaseDialogInner?.querySelector('.releaseChrome');
  if(!chrome)return;
  chrome.classList.remove('chromePointerActive');
  releaseChromeHoverSuppressed=releaseChromePointerInside(chrome)
}
function setupReleaseChromePointerVisibility(){
  const chrome=releaseDialogInner?.querySelector('.releaseChrome');
  if(!chrome||chrome.dataset.pointerVisibilityReady)return;
  chrome.dataset.pointerVisibilityReady='1';
  chrome.addEventListener('pointerenter',e=>{
    if(e.pointerType==='touch'||releaseChromeHoverSuppressed)return;
    chrome.classList.add('chromePointerActive')
  });
  chrome.addEventListener('pointerleave',()=>{
    chrome.classList.remove('chromePointerActive');
    releaseChromeHoverSuppressed=false
  })
}
setupReleaseChromePointerVisibility();

