function searchResultCard(id,x,i){const source=x.source_url?`<a href="${safe(x.source_url)}" target="_blank" rel="noopener">${esc(x.provider)}</a>`:esc(x.provider),noSeeds=x.accepted&&(Number(x.seeds)||0)===0;return `<article class="row searchResult ${x.accepted?'accepted':'rejected'}${noSeeds?' noSeeds':''}" data-index="${i}"><div><b>${esc(x.title)}</b><div class="searchResultMeta"><small class="searchSource">Source: ${source}${x.size?' · '+esc(x.size):''}</small>${searchSwarmLabel(x)}</div><small class="searchMatch">${noSeeds?'⚠ Preferred filename match, but currently has no seeders · ':''}${searchMatchLabel(x)}</small>${searchFilesMarkup(x)}</div><span class="matchState">${noSeeds?'⚠ Accepted · 0 seeds':x.accepted?'✓ Accepted':'✕ Rejected'}</span><div class="actions"><button ${!x.accepted?'disabled':''} onclick="downloadResult(${id},${i})">⬇ Download</button>${!x.accepted?`<button class="danger" onclick="forceDownload(${id},${i})">⚠ Force download</button>`:''}</div></article>`}
function renderSearchResults(id){const ordered=searchDialog._results||[],query=searchResultFilter.value.trim().toLowerCase(),visible=query?ordered.filter(x=>[x.title,x.provider].join(' ').toLowerCase().includes(query)):ordered,bySeeds=(a,b)=>(Number(b.seeds)||0)-(Number(a.seeds)||0),accepted=visible.filter(x=>x.accepted).slice().sort(bySeeds),rejected=visible.filter(x=>!x.accepted).slice().sort(bySeeds),group=(title,items,acceptedGroup)=>items.length?`<section class="searchGroup ${acceptedGroup?'acceptedGroup':'filteredGroup'}"><header><h3>${acceptedGroup?'✓':'✕'} ${title}</h3><span>${items.length}</span></header><div class="searchResultGrid">${items.map(x=>searchResultCard(id,x,ordered.indexOf(x))).join('')}</div></section>`:'';searchResults.innerHTML=`<p class="searchSummary">${visible.length} of ${ordered.length} release-ID matches shown · ${accepted.length} accepted by filename patterns · sorted by match, then seeders</p>`+(visible.length?group('Accepted matches',accepted,true)+group('Filtered matches',rejected,false):`<div class="empty">${ordered.length?'No results match this filter.':'No results found for this release ID.'}</div>`)}
function searchSwarmLabel(x){const seeds=Number(x.seeds)||0,peers=Number(x.peers)||0;return `<span class="searchSwarm"><span class="swarmSeeds" title="Seeders">▲ ${seeds}</span><span class="swarmPeers" title="Peers">▼ ${peers}</span></span>`}
async function searchRelease(id,download){cancelSearchAutoClose();searchResults.innerHTML='<div class="empty">Searching provider and checking torrent detail pages…</div>';searchResultFilter.value='';searchDialog.showModal();try{const rows=await api(`/releases/${id}/search`),ordered=[...rows].sort((a,b)=>Number(b.accepted)-Number(a.accepted));searchDialog.dataset.release=id;searchDialog._results=ordered;renderSearchResults(id);const accepted=ordered.filter(x=>x.accepted).sort((a,b)=>(Number(b.seeds)||0)-(Number(a.seeds)||0));if(download){if(accepted.length&&(Number(accepted[0].seeds)||0)>0)await downloadResult(id,ordered.indexOf(accepted[0]),false,true);else if(accepted.length)toast('Preferred match has 0 seeders · choose a result manually');else toast('No torrent file matched Accepted filename patterns')}}catch(e){searchResults.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
searchDialog.addEventListener('close',()=>{cancelSearchAutoClose();if(searchDialog._downloadSucceeded){const releaseID=searchDialog._downloadSucceeded;searchDialog._downloadSucceeded=null;refreshReleaseAfterDownload(releaseID)}});
async function refreshReleaseAfterDownload(releaseID){try{await Promise.all([loadStats(),loadReleases(),loadMonitoredReleases()]);if(releaseDialog.open&&activeReleaseID===releaseID)renderReleaseDetail(await api('/releases/'+releaseID))}catch(e){}}
let searchAutoCloseTimer=null;
function cancelSearchAutoClose(){if(searchAutoCloseTimer){clearInterval(searchAutoCloseTimer);searchAutoCloseTimer=null}if(searchAutoCloseNotice){searchAutoCloseNotice.hidden=true;searchAutoCloseNotice.textContent=''}}
function startSearchDialogAutoClose(){cancelSearchAutoClose();const raw=settings.search_auto_close_seconds;let remaining=(raw===undefined||raw==='')?5:Math.max(0,parseInt(raw,10)||0);if(remaining<=0){searchDialog.close();return}const render=()=>{searchAutoCloseNotice.hidden=false;searchAutoCloseNotice.innerHTML=`✓ Match found and submitted to qBittorrent · closing in ${remaining}s… <button type="button" class="linkButton" id="searchAutoCloseCancel">Keep open</button>`;const cancelBtn=$('#searchAutoCloseCancel');if(cancelBtn)cancelBtn.onclick=cancelSearchAutoClose};render();searchAutoCloseTimer=setInterval(()=>{remaining--;if(remaining<=0){cancelSearchAutoClose();searchDialog.close();return}render()},1000)}
async function submitSearchResult(id,index,forced,close,autoClose=false,replaceExisting=false){const x=searchDialog._results[index],row=document.querySelector(`.searchResult[data-index="${index}"]`),buttons=row?.querySelectorAll('button')||[],state=row?.querySelector('.matchState');buttons.forEach(b=>b.disabled=true);if(state)state.textContent=replaceExisting?'Replacing…':forced?'Forcing…':'Submitting…';try{const result=await api(`/releases/${id}/download`,{method:'POST',body:JSON.stringify({...x,forced,replace_existing:replaceExisting})});if(result.status==='skipped'&&result.can_replace&&!replaceExisting){const replace=confirm('A download is already running for this release ID.\n\nRemove it from qBittorrent, DELETE its incomplete downloaded files, clear all JAVBeacon download history for this release, and replace it with this torrent?');if(replace)return submitSearchResult(id,index,forced,close,autoClose,true)}const success=result.status==='downloading';if(state){state.textContent=result.status==='skipped'?'Skipped':result.status==='failed'?'Rejected':forced?'⚠ Forced · Downloading':'✓ Downloading';state.classList.toggle('accepted',success);state.classList.toggle('rejected',!success)}toast(result.status==='skipped'?'Download skipped: '+result.match_reason:result.status==='failed'?'Download rejected: '+result.error:replaceExisting?'Existing download deleted and replacement started':forced?'Forced download submitted to qBittorrent':'Accepted torrent submitted to qBittorrent');if(success){searchDialog._downloadSucceeded=id;downloadStatus='downloading';$$('.downloadTabs button').forEach(b=>b.classList.toggle('active',b.dataset.downloadStatus==='downloading'));downloadPage=0;if(close)searchDialog.close();else if(autoClose)startSearchDialogAutoClose()}loadDownloads()}catch(e){buttons.forEach(b=>b.disabled=false);toast(e.message)}}
async function downloadResult(id,index,close=true,autoClose=false){return submitSearchResult(id,index,false,close,autoClose)}
async function forceDownload(id,index){if(!confirm('Force download this result even though automatic matching rejected it?\n\nThis bypasses the accepted-filename check for this one torrent only. The override is recorded in download history so it is never confused with a normal accepted match.'))return;return submitSearchResult(id,index,true,false)}
function switchView(name,persist=true){prefs.activeMenu=name;$$('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$$('.view').forEach(v=>v.hidden=v.id!==name+'View');statsBar.hidden=name!=='sites';pageTitle.textContent={releases:'Release library',monitoring:'Download monitoring',notifications:'Notifications',missing:'Missing library files',sites:'Monitoring sites',activity:'Jobs',logs:'Live server logs',settings:'Settings'}[name]||'JAVBeacon';if(name==='monitoring'){loadDownloads();loadMonitoredReleases();if(Object.keys(settings).length)pollDownloadSearch()}if(name==='notifications')loadNotifications();if(name==='missing'){loadMissingScenes();refreshMissingScanStatus()}if(name==='activity'){pollJob();pollStash();loadJobHistory()}if(name==='logs')loadLogs();if(name==='settings')pollCoverCache();if(persist)savePreferences()}
function monitoringTab(name,persist=true){prefs.monitoringTab=name;$$('.monitoringTabs button').forEach(b=>b.classList.toggle('active',b.dataset.monitoringTab===name));downloadActivityPanel.hidden=name!=='downloads';monitoredReleasesPanel.hidden=name!=='monitored';if(persist)savePreferences()}
// settingsTab/applySettingsFilter group the Settings form's growing panel
// count into tabs (TODO-2.0's Settings overhaul), each panel tagged with a
// data-settings-tab attribute. A non-empty search query overrides the tab
// filter entirely - it matches across every panel's full text (heading,
// labels, help text) via the same wildcardMatch used elsewhere in the app,
// so a panel surfaces regardless of which tab it lives under.
function settingsTab(name,persist=true){prefs.settingsTab=name;$$('.settingsTabs button').forEach(b=>b.classList.toggle('active',b.dataset.settingsTab===name));applySettingsFilter();if(persist)savePreferences()}
function applySettingsFilter(){const q=(settingsSearch?.value||'').trim(),activeTab=prefs.settingsTab||'general';$$('.settingsGrid>.panel').forEach(p=>{p.hidden=q?!wildcardMatch(p.textContent,q):(p.dataset.settingsTab||'general')!==activeTab})}
function statusTab(value,desired=false,persist=true){prefs.activeTab=value||'';prefs.desired=desired;$$('#releasesView .subtabs button').forEach(b=>b.classList.toggle('active',(b.dataset.status||'')===prefs.activeTab&&String(!!b.dataset.desired)===String(!!desired)));if(persist){savePreferences();loadReleases()}}
function clearReleaseFilterState(){prefs.activeTab='';prefs.desired=false;prefs.category=prefs.category||'Actress';prefs.entries=[];prefs.search='';prefs.searchExpression={logic:'and',conditions:[]};prefs.activePreset=null;search.value='';categoryFilter.value=prefs.category;entryFilter.value='';syncReleaseToggles();statusTab('',false,false);savePreferences();loadReleases();loadPresets();toast('Release filters cleared')}
async function loadPresets(){presets=await api('/filter-presets');presetMenuItems.innerHTML=`<header><b>Saved filter sets</b><small>${presets.length}</small></header><label class="presetSearch">⌕ <input id="presetMenuSearch" type="search" placeholder="Type partial name or * wildcard" autocomplete="off"></label><div id="presetRows">${presets.length?presets.map(x=>`<div class="presetMenuRow ${x.id===prefs.activePreset?'active':''}" data-preset-id="${x.id}"><button class="presetApply" type="button" onclick="applyPreset(${x.id})">${esc(x.name)}</button><button type="button" class="presetManage" title="Rename filter set" aria-label="Rename filter set" onclick="renamePreset(${x.id})">✎</button><button type="button" class="presetManage danger" title="Delete filter set" aria-label="Delete filter set" onclick="deletePreset(${x.id})">×</button></div>`).join(''):'<p class="presetMenuEmpty">No saved filter sets yet.</p>'}</div>`;presetMenuSearch.oninput=filterPresetMenu;presetMenuSearch.onkeydown=e=>{if(e.key!=='Enter')return;e.preventDefault();const first=filteredPresets()[0];if(first)applyPreset(first.id)};filterPresetMenu()}
function filteredPresets(){const query=presetMenuSearch?.value||'';return presets.filter(x=>wildcardMatch(x.name,query))}
function filterPresetMenu(){const visible=new Set(filteredPresets().map(x=>x.id));$$('.presetMenuRow').forEach(row=>row.hidden=!visible.has(Number(row.dataset.presetId)))}
function currentReleaseFilterState(overrides={}){return{activeTab:prefs.activeTab||'',category:prefs.category||'',entries:[...(prefs.entries||[])],search:prefs.search||'',searchExpression:prefs.searchExpression||{logic:'and',conditions:[]},sortField:prefs.sortField||'release',sortDirection:prefs.sortDirection||'desc',hideLocal:!!prefs.hideLocal,hideLocalTransparency:!!prefs.hideLocalTransparency,showNonPreferred:!!prefs.showNonPreferred,desired:!!prefs.desired,coverZoom:Number(prefs.coverZoom)||280,...overrides}}
async function saveFilterSet(state){const name=prompt('Filter set name');if(!name?.trim())return;const x=await api('/filter-presets',{method:'POST',body:JSON.stringify({name:name.trim(),state})});prefs.activePreset=x.id;await loadPresets();savePreferences();toast('Filter set saved')}
function applyPreset(id){const x=presets.find(p=>p.id===Number(id));if(!x)return;prefs={...prefs,...x.state,activePreset:x.id};syncPreferenceControls();presetMenu.open=false;loadPresets();savePreferences();loadReleases();toast(`Applied saved filter: ${x.name}`)}
async function renamePreset(id){const x=presets.find(p=>p.id===Number(id));if(!x)return;const name=prompt('Rename filter set',x.name);if(!name?.trim())return;await api('/filter-presets/'+x.id,{method:'PUT',body:JSON.stringify({...x,name:name.trim()})});await loadPresets();toast(`Renamed filter set to: ${name.trim()}`)}
async function deletePreset(id){const x=presets.find(p=>p.id===Number(id));if(!x||!confirm(`Delete saved filter “${x.name}”?`))return;await api('/filter-presets/'+x.id,{method:'DELETE'});if(prefs.activePreset===x.id)prefs.activePreset=null;await loadPresets();savePreferences();toast(`Deleted saved filter: ${x.name}`)}
// conditionValueListID maps a condition field to the id of the <datalist>
// (populated by populateConditionOptions) that offers a live-search picker
// of existing values for that field. Fields with no bounded value set -
// title and description are free text - return '' so the value input falls
// back to a plain text box with no suggestions.
function conditionValueListID(field){return{tag:'conditionTagOptions',actress:'conditionActressOptions',studio:'conditionStudioOptions',label:'conditionLabelOptions'}[field]||''}
// populateConditionOptions fills the tag/actress datalists shared by every
// condition row from the currently loaded releases, mirroring how
// populateEntries() derives the toolbar's entry picker - so typing in a
// condition's value field offers a live-search list of real existing values
// instead of requiring the user to know the exact spelling up front.
function populateConditionOptions(){for(const field of['tag','actress','studio','label'])populateMetadataOptions(field,document.getElementById(conditionValueListID(field)))}
// conditionRow renders one AND/OR condition row. c may be a partial object
// (e.g. the {} fallback openConditions() uses for a brand-new, empty
// condition set) so every field is defaulted individually rather than
// trusting the whole object to be complete - assigning an undefined value
// straight into a text <input>'s .value coerces to the literal string
// "undefined", which is what previously showed up in a fresh Value field
// and, if left in place, made every applied filter search for that literal
// text and match nothing.
const releaseConditionFields=[['title','Title'],['tag','Tag'],['actress','Actress'],['description','Description'],['studio','Studio'],['label','Label'],['duration','Duration'],['o_count','O Count (StashApp)'],['play_count','Play Count (StashApp)'],['last_o_count','Last O count date (StashApp)'],['last_played','Last Played (StashApp)'],['added_at','Date added'],['updated_at','Date updated'],['release_date','Release Date'],['desired','Desired'],['downloaded','Downloaded'],['download_started','Download started'],['download_failed','Download failed'],['local','Locally available (StashApp)'],['monitored','Monitored']];
function releaseConditionKind(field){if(['duration','o_count','play_count'].includes(field))return'numeric';if(['last_o_count','last_played','added_at','updated_at','release_date'].includes(field))return'date';if(['desired','downloaded','download_started','download_failed','local','monitored'].includes(field))return'bool';return'text'}
function updateConditionRow(row){const field=row.querySelector('[name=field]').value,kind=releaseConditionKind(field),value=row.querySelector('[name=value]'),boolValue=row.querySelector('[name=boolValue]'),op=row.querySelector('[name=op]'),exact=row.querySelector('[data-toggle=exact]'),wildcard=row.querySelector('[data-toggle=wildcard]'),listID=conditionValueListID(field);value.hidden=kind==='bool';boolValue.hidden=kind!=='bool';value.type=kind==='numeric'?'number':kind==='date'?'date':'text';value.step=kind==='numeric'?'any':'';op.hidden=kind!=='numeric'&&kind!=='date';if(kind==='numeric')op.innerHTML='<option value="gte">at least / minimum</option><option value="lte">at most / maximum</option><option value="eq">equals</option><option value="gt">greater than</option><option value="lt">less than</option>';if(kind==='date')op.innerHTML='<option value="after">after</option><option value="before">before</option>';exact.hidden=wildcard.hidden=kind!=='text';if(listID)value.setAttribute('list',listID);else value.removeAttribute('list')}
function conditionRow(c={},container=conditions){const n=document.createElement('div');n.className='condition';n.innerHTML=`<select name="field">${releaseConditionFields.map(([value,label])=>`<option value="${value}">${label}</option>`).join('')}</select><input name="value" type="text" placeholder="Value" autocomplete="off"><select name="boolValue" hidden><option value="true">Yes</option><option value="false">No</option></select><select name="op" hidden></select><label data-toggle="exact"><input name="exact" type="checkbox"> Exact</label><label data-toggle="wildcard"><input name="wildcard" type="checkbox"> Wildcard</label><button type="button">×</button>`;const fieldEl=n.querySelector('[name=field]'),valueEl=n.querySelector('[name=value]');fieldEl.value=c.field||'title';n.querySelector('[name=exact]').checked=!!c.exact;n.querySelector('[name=wildcard]').checked=!!c.wildcard;updateConditionRow(n);valueEl.value=c.value||'';n.querySelector('[name=boolValue]').value=c.value==='false'?'false':'true';if(c.op)n.querySelector('[name=op]').value=c.op;fieldEl.onchange=()=>updateConditionRow(n);valueEl.oninput=()=>{const id=conditionValueListID(fieldEl.value);if(id)populateMetadataOptions(fieldEl.value,document.getElementById(id),valueEl.value)};n.querySelector('button').onclick=()=>n.remove();container.append(n)}
// normalizeGroupedExpression normalizes either shape of a SearchExpression
// (TODO-2.0 Task A "AND/OR condition groups") into {logic, groups:[...]}
// for editing in a Conditions dialog: the new grouped shape passes through
// as-is; a legacy flat shape (top-level "conditions", no "groups" - from a
// preset/URL saved before this feature existed) becomes a single implicit
// group using the old top-level logic, exactly mirroring how the backend
// (releaseFilterWhere/stashMissingFilterWhere) interprets the same legacy
// shape, so editing and re-saving an old preset doesn't change what it
// matches. Shared by both the Release Library and Missing Library Files
// Conditions dialogs.
function normalizeGroupedExpression(expr){expr=expr||{};if(expr.groups?.length)return{logic:expr.logic||'and',groups:expr.groups};if(expr.conditions?.length)return{logic:'and',groups:[{logic:expr.logic||'and',conditions:expr.conditions}]};return{logic:expr.logic||'and',groups:[]}}
// conditionGroupEl renders one AND/OR condition group: its own Match
// (AND/OR) select over its own condition rows, a "+ Condition" button
// scoped to this group, and a "Remove group" button. Mirrors conditionRow's
// tolerance of a partial/empty group object.
function conditionGroupEl(g={}){const n=document.createElement('div');n.className='conditionGroup';n.innerHTML=`<div class="conditionGroupHeader"><label>Match<select name="groupLogic"><option value="and">All (AND)</option><option value="or">Any (OR)</option></select></label><button type="button" class="removeGroup" title="Remove this group">🗑 Remove group</button></div><div class="groupConditions"></div><button type="button" class="addConditionToGroup">+ Condition</button>`;n.querySelector('[name=groupLogic]').value=g.logic||'and';const rows=n.querySelector('.groupConditions');(g.conditions?.length?g.conditions:[{}]).forEach(c=>conditionRow(c,rows));n.querySelector('.addConditionToGroup').onclick=()=>conditionRow({},rows);n.querySelector('.removeGroup').onclick=()=>{n.remove();if(!conditions.children.length)appendConditionGroup()};return n}
function appendConditionGroup(g){conditions.append(conditionGroupEl(g))}
function openConditions(){conditions.innerHTML='';populateConditionOptions();const expr=normalizeGroupedExpression(prefs.searchExpression);conditionsForm.elements.logic.value=expr.logic;(expr.groups.length?expr.groups:[{logic:'and',conditions:[{}]}]).forEach(appendConditionGroup);conditionsDialog.showModal()}
function expressionFromForm(){const groups=[...conditions.querySelectorAll('.conditionGroup')].map(g=>({logic:g.querySelector('[name=groupLogic]').value,conditions:[...g.querySelectorAll('.condition')].map(n=>{const field=n.querySelector('[name=field]').value,kind=releaseConditionKind(field);if(kind==='bool')return{field,value:n.querySelector('[name=boolValue]').value};const value=n.querySelector('[name=value]').value.trim();if(!value)return null;if(kind==='numeric'||kind==='date')return{field,value,op:n.querySelector('[name=op]').value};return{field,value,exact:n.querySelector('[name=exact]').checked,wildcard:n.querySelector('[name=wildcard]').checked}}).filter(Boolean)})).filter(g=>g.conditions.length);return{logic:conditionsForm.elements.logic.value,groups}}
// ---- Missing Library Files (TODO-2.0 Phase 2) - StashApp scenes whose
// underlying video file was lost. Filters/pagination mirror the Releases
// Conditions dialog and the Notifications page/select-all pattern; job
// polling mirrors pollReleaseRefresh/pollStash (poll a {running,...}
// status endpoint until running:false).
let missingRows=[],missingSelection=new Set(),missingPage=0;
function missingStatusLabel(s){return{missing:'Missing',retrieving:'Retrieving',retrieve_failed:'Retrieve Failed',retrieved:'Retrieved',monitored:'Monitored',downloading:'Downloading',downloaded:'Downloaded',failed:'Failed'}[s]||s||'Unknown'}
// missingFieldKind drives which controls a condition row shows: text
// fields get wildcard(/exact), numeric fields get a value+op pair, date
// gets a date input+op, bool fields get a Yes/No select instead of value.
function missingFieldKind(field){if(field==='o_count'||field==='play_count')return'numeric';if(field==='last_played')return'date';if(field==='has_javlibrary_url'||field==='has_db_entry')return'bool';return'text'}
function updateMissingConditionRow(row){const field=row.querySelector('[name=field]').value,kind=missingFieldKind(field),value=row.querySelector('[name=value]'),boolValue=row.querySelector('[name=boolValue]'),op=row.querySelector('[name=op]'),exact=row.querySelector('[data-toggle=exact]'),wildcard=row.querySelector('[data-toggle=wildcard]');value.hidden=kind==='bool';boolValue.hidden=kind!=='bool';value.type=kind==='numeric'?'number':kind==='date'?'date':'text';op.hidden=kind!=='numeric'&&kind!=='date';if(kind==='numeric')op.innerHTML='<option value="gte">at least</option><option value="lte">at most</option><option value="eq">equals</option><option value="gt">greater than</option><option value="lt">less than</option>';if(kind==='date')op.innerHTML='<option value="after">after</option><option value="before">before</option>';exact.hidden=field!=='studio';wildcard.hidden=!(field==='path'||field==='studio'||field==='tag')}
function missingConditionRow(c={},container=missingConditionRows){const n=document.createElement('div');n.className='condition missingCondition';n.innerHTML=`<select name="field"><option value="path">Path</option><option value="studio">Studio</option><option value="tag">Tag</option><option value="o_count">O-Counter</option><option value="play_count">Play Count</option><option value="last_played">Last Played</option><option value="has_javlibrary_url">Has JavLibrary URL</option><option value="has_db_entry">Already in JAVBeacon database</option></select><input name="value" type="text" placeholder="Value"><select name="boolValue" hidden><option value="true">Yes</option><option value="false">No</option></select><select name="op" hidden></select><label class="check compact" data-toggle="exact"><input name="exact" type="checkbox"> Exact</label><label class="check compact" data-toggle="wildcard"><input name="wildcard" type="checkbox"> Wildcard</label><button type="button">×</button>`;const fieldEl=n.querySelector('[name=field]');fieldEl.value=c.field||'path';n.querySelector('[name=exact]').checked=!!c.exact;n.querySelector('[name=wildcard]').checked=!!c.wildcard;updateMissingConditionRow(n);n.querySelector('[name=value]').value=c.value||'';n.querySelector('[name=boolValue]').value=c.value==='false'?'false':'true';if(c.op)n.querySelector('[name=op]').value=c.op;fieldEl.onchange=()=>updateMissingConditionRow(n);n.querySelector('button').onclick=()=>n.remove();container.append(n)}
// missingConditionGroupEl mirrors conditionGroupEl (see its doc comment)
// for the Missing Library Files Conditions dialog's field set.
function missingConditionGroupEl(g={}){const n=document.createElement('div');n.className='conditionGroup';n.innerHTML=`<div class="conditionGroupHeader"><label>Match<select name="groupLogic"><option value="and">All (AND)</option><option value="or">Any (OR)</option></select></label><button type="button" class="removeGroup" title="Remove this group">🗑 Remove group</button></div><div class="groupConditions"></div><button type="button" class="addConditionToGroup">+ Condition</button>`;n.querySelector('[name=groupLogic]').value=g.logic||'and';const rows=n.querySelector('.groupConditions');(g.conditions?.length?g.conditions:[{}]).forEach(c=>missingConditionRow(c,rows));n.querySelector('.addConditionToGroup').onclick=()=>missingConditionRow({},rows);n.querySelector('.removeGroup').onclick=()=>{n.remove();if(!missingConditionRows.children.length)appendMissingConditionGroup()};return n}
function appendMissingConditionGroup(g){missingConditionRows.append(missingConditionGroupEl(g))}
function openMissingConditions(){missingConditionRows.innerHTML='';const expr=normalizeGroupedExpression(prefs.missingSearchExpression);missingConditionsForm.elements.logic.value=expr.logic;(expr.groups.length?expr.groups:[{logic:'and',conditions:[{}]}]).forEach(appendMissingConditionGroup);missingConditionsDialog.showModal()}
function missingExpressionFromForm(){const groups=[...missingConditionRows.querySelectorAll('.conditionGroup')].map(g=>({logic:g.querySelector('[name=groupLogic]').value,conditions:[...g.querySelectorAll('.missingCondition')].map(n=>{const field=n.querySelector('[name=field]').value,kind=missingFieldKind(field);if(kind==='bool')return{field,value:n.querySelector('[name=boolValue]').value};const value=n.querySelector('[name=value]').value.trim();if(!value)return null;if(kind==='numeric')return{field,value,op:n.querySelector('[name=op]').value||'gte'};if(kind==='date')return{field,value,op:n.querySelector('[name=op]').value||'after'};return{field,value,exact:n.querySelector('[name=exact]').checked,wildcard:n.querySelector('[name=wildcard]').checked}}).filter(Boolean)})).filter(g=>g.conditions.length);return{logic:missingConditionsForm.elements.logic.value,groups}}
// missingPageSizeLimit parses the free-entry Page size field: "All" (any
// case) requests one page big enough to hold the whole missing-file
// backlog (matching the store's stashMissingMaxLimit cap server-side), a
// blank/non-numeric/non-positive value falls back to the 25 default, and
// anything else is used as-is - this is a plain text input rather than a
// fixed dropdown specifically so a page size outside the usual presets can
// be typed in directly (TODO-2.0 Task A).
function missingPageSizeLimit(){const raw=String(missingPageSize?.value??'').trim();if(/^all$/i.test(raw))return 5000;const n=parseInt(raw,10);return Number.isFinite(n)&&n>0?n:25}
function missingQuery(){const limit=missingPageSizeLimit(),params=new URLSearchParams({status:prefs.missingStatus||'',search_expression:JSON.stringify(prefs.missingSearchExpression||{logic:'and',conditions:[]}),sort:prefs.missingSort||'',direction:prefs.missingDirection||'desc',limit:String(limit),offset:String(missingPage*limit)});return{params,limit}}
function syncMissingControls(){$$('#missingView .missingTabs button').forEach(b=>b.classList.toggle('active',(b.dataset.missingStatus||'')===(prefs.missingStatus||'')));missingSortField.value=prefs.missingSort||'';missingSortDirection.textContent=(prefs.missingDirection||'desc')==='asc'?'↑':'↓';missingPageSize.value=prefs.missingPageSize||25}
// missingRowCard mirrors the Release Library card's and Notifications
