async function pollMissingScan(){try{const j=await api('/jobs/stash-missing-scan');if(j.scenes>0){missingJobProgress.max=j.scenes;missingJobProgress.value=j.processed||0}else{missingJobProgress.removeAttribute('value')}missingJobStatus.textContent=j.running?`Scanning… ${j.processed||0}/${j.scenes||'?'} scenes checked · ${j.missing||0} missing · ${j.matched||0} matched${j.current_item?' · checking '+j.current_item:''}`:j.error?'✕ '+j.error:`Scan complete · ${j.scenes||0} scenes checked · ${j.missing||0} missing · ${j.matched||0} matched`;if(j.running){setTimeout(pollMissingScan,1000);return}missingJobProgress.value=missingJobProgress.max||1;refreshMissingScanStatus();if(!j.error)toast(`Scan complete · ${j.missing||0} missing found`);missingPage=0;loadMissingScenes()}catch(e){missingJobStatus.textContent='✕ '+e.message}}
