function setupDownloadActivityControls(){if(!$('#downloadStalledOnly'))downloadFilenamePatternExcluded.closest('label').insertAdjacentHTML('afterend','<label class="check compact" title="No seeders and never seen complete, or not seen complete within the selected age"><input id="downloadStalledOnly" type="checkbox"> Stalled</label><label class="compact">Complete age (days)<input id="downloadStalledDays" type="number" min="1" value="7" style="width:68px"></label>');if(!downloadSortField.querySelector('[value="seeds"]'))downloadSortField.insertAdjacentHTML('beforeend','<option value="seeds">Seeds</option><option value="peers">Peers</option><option value="seen_complete">Last seen complete</option>');if(!$('#downloadBulkBar'))downloadList.insertAdjacentHTML('beforebegin','<div id="downloadBulkBar" class="bulkBar" hidden><span id="downloadSelectedCount">0 selected</span><button id="downloadBulkDelete" class="danger" type="button">🗑 Delete selected</button><button id="downloadBulkClear" type="button">Clear selection</button></div>')}
