const downloadStalledOnly=$('#downloadStalledOnly'),downloadStalledDays=$('#downloadStalledDays'),downloadBulkBar=$('#downloadBulkBar'),downloadSelectedCount=$('#downloadSelectedCount'),downloadBulkDelete=$('#downloadBulkDelete'),downloadBulkClear=$('#downloadBulkClear');
function downloadQuery(){const limit=Number(downloadPageSize.value)||25,params=new URLSearchParams({status:downloadStatus,sort:prefs.downloadSort||'updated',direction:prefs.downloadDirection||'desc',limit:String(limit),offset:String(downloadPage*limit)});if(downloadSearch.value.trim())params.set('search',downloadSearch.value.trim());if(downloadSourceFilter.value.trim())params.set('source',downloadSourceFilter.value.trim());if(downloadFilenamePatternExcluded.checked)params.set('filename_pattern_excluded','true');if(downloadStalledOnly.checked){params.set('stalled','true');params.set('stalled_days',String(Math.max(1,Number(downloadStalledDays.value)||7)))}return{params,limit}}
function toggleDownloadSelect(id,checked){if(checked)downloadSelected.add(id);else downloadSelected.delete(id);renderDownloadBulkBar()}
