async function loadDownloads(manual=false){if(downloadLoading)return;downloadLoading=true;refreshDownloadActivity.disabled=true;downloadRefreshStatus.textContent='Refreshing…';try{const{params,limit}=downloadQuery(),j=await api('/downloads?'+params.toString()),rows=j.items||[],total=j.total||0;downloadVisibleIDs=rows.map(x=>x.id);const body=rows.map(x=>{const progress=Math.max(0,Math.min(100,Math.round((x.status==='completed'?1:Number(x.progress)||0)*100))),release=x.release_id?`<a class="downloadCover" href="/release/${x.release_id}" onclick="if(!event.ctrlKey&&!event.metaKey&&!event.shiftKey){event.preventDefault();openRelease(${x.release_id})}"><img loading="lazy" src="/covers/${x.release_id}" alt="${esc(x.video_id||x.query)}"></a>`:'<span class="downloadCover placeholder">↓</span>',detail=esc(x.error||x.match_reason||x.qb_response||'');return `<article class="downloadTableRow"><label class="check compact downloadRowSelect" title="Select download"><input type="checkbox" ${downloadSelected.has(x.id)?'checked':''} onchange="toggleDownloadSelect(${x.id},this.checked)"></label>${release}<div class="downloadIdentity"><b>${esc(x.video_id||x.query||'Unknown release')}</b><span title="${attr(x.name)}">${esc(x.name||x.provider||'Torrent pending')}</span><small>${esc(x.provider)}${x.source_type?' · '+esc(x.source_type):''}</small>${x.filename_pattern_excluded?'<span class="badge nonPreferredBadge" title="Submitted despite not being a normal accepted-filename match (manually forced, or the Missing Library Files non-preferred-filename fallback)">⚠ Non-preferred filename</span>':''}</div><div class="downloadProgress"><div><span>${progress}%</span><small>${esc(x.status)}</small></div><progress max="100" value="${progress}"></progress>${detail?`<small title="${attr(detail)}">${detail}</small>`:''}</div><div class="downloadSwarm"><span><b>${Number(x.seeds)||0}</b> seeds</span><span><b>${Number(x.peers)||0}</b> peers</span><small>Ratio ${Number(x.seed_ratio||0).toFixed(2)}</small></div><div class="downloadTiming"><span><b>ETA</b> ${formatETA(x.eta_seconds)}</span><small>Last seen complete: ${formatSeenComplete(x.seen_complete)}</small><small>Added ${new Date(x.added_at).toLocaleString()}</small></div><div class="downloadState"><span class="downloadStatus ${esc(x.status)}">${esc(x.status)}</span>${x.post_status?`<small>${esc(x.post_status.replaceAll('_',' '))}</small>`:''}</div><button class="danger downloadRemove" title="Remove torrent and clear download history" onclick="removeDownload(${x.id})">🗑<span> Remove</span></button></article>`}).join('');downloadList.innerHTML=rows.length?`<div class="downloadTable bulkSelectable"><div class="downloadTableHead"><label class="check compact downloadRowSelect" title="Select all visible"><input type="checkbox" ${rows.length&&rows.every(x=>downloadSelected.has(x.id))?'checked':''} onchange="toggleDownloadSelectAll(this.checked)"></label><span>Release</span><span>Progress</span><span>Seeds / peers</span><span>Timing / last complete</span><span>State</span><span></span></div>${body}</div>`:'<div class="empty">No downloads in this state.</div>';renderDownloadBulkBar();renderDownloadPagination(total,limit);downloadRefreshStatus.textContent=`Updated ${new Date().toLocaleTimeString()} · ${total} item${total===1?'':'s'}`;if(manual)toast('Download activity refreshed')}catch(e){downloadList.innerHTML=`<div class="empty">${esc(e.message)}</div>`;downloadPagination.innerHTML='';downloadRefreshStatus.textContent='Refresh failed';if(manual)toast(e.message)}finally{downloadLoading=false;refreshDownloadActivity.disabled=false}}
async function bulkDeleteDownloads(){if(!downloadSelected.size)return;if(!confirm(`Delete ${downloadSelected.size} selected download(s)?\n\nThe torrents and their incomplete downloaded files will be deleted from qBittorrent, and JAVBeacon history will be cleared.`))return;const replace=confirm('After deleting them, search for and download fresh replacements in the background?');try{const result=await api('/downloads/bulk-remove',{method:'POST',body:JSON.stringify({ids:[...downloadSelected],replace})});downloadSelected.clear();renderDownloadBulkBar();toast(`${result.queued} release${result.queued===1?'':'s'} queued for background ${replace?'replacement':'deletion'}`);setTimeout(()=>loadDownloads(),750)}catch(e){toast(e.message)}}
