function renderMonitoredPagination(total,limit){const pages=Math.max(1,Math.ceil(total/limit));if(monitoredPage>pages-1)monitoredPage=Math.max(0,pages-1);monitoredPagination.innerHTML=total?`<button ${monitoredPage<=0?'disabled':''} onclick="changeMonitoredPage(-1)">‹ Prev</button><span>Page ${monitoredPage+1} of ${pages} · ${total} total</span><button ${monitoredPage>=pages-1?'disabled':''} onclick="changeMonitoredPage(1)">Next ›</button>`:''}
