async function loadMonitoredReleases(){try{const{params,limit}=monitoredQuery(),[rows,count]=await Promise.all([api('/releases?'+params.toString()),api('/releases/count?'+params.toString())]),total=count.total||0;monitoredReleaseCount.textContent=`${total} active`;const body=rows.map(x=>{const flags=[x.desired?'♥ Desired':'',x.notify_on_release?'🔔 Notify':'',x.allow_non_preferred_filenames?'⚠ Non-preferred allowed':''].filter(Boolean).join(' · ');return `<article class="downloadTableRow" data-release="${x.id}"><label class="check compact monitoredRowSelect" title="Select for bulk actions"><input type="checkbox" ${monitoredSelected.has(x.id)?'checked':''} onchange="toggleMonitoredSelect(${x.id},this.checked)"></label><a class="downloadCover" href="/release/${x.id}" onclick="if(!event.ctrlKey&&!event.metaKey&&!event.shiftKey){event.preventDefault();openRelease(${x.id})}"><img loading="lazy" src="/covers/${x.id}" alt="${attr(x.video_id)}"></a><div class="downloadIdentity"><b>${esc(x.video_id)}</b><span title="${attr(x.title)}">${esc(x.title)}</span><small>${esc(x.site_title)}${x.site_monitor_download?' · Site managed':''}</small></div><div class="downloadProgress"><div><span>${esc(x.release_date||'Date unknown')}</span><small>Release date</small></div></div><div class="downloadSwarm"><span><b>${esc(x.site_title||'—')}</b>Site</span><span><b>${flags||'—'}</b>Flags</span></div><div class="downloadTiming"><span><b>Added</b> ${x.added_at?new Date(x.added_at).toLocaleDateString():'Unknown'}</span><small>Updated ${x.updated_at?new Date(x.updated_at).toLocaleString():'Unknown'}</small></div><div class="downloadState"><span class="downloadStatus">Monitored</span>${x.site_monitor_download?'<small>Site managed</small>':''}</div>${x.site_monitor_download?'<button class="downloadRemove" disabled title="Change the site Download + Search mode to remove inherited monitoring">📡</button>':`<button class="downloadRemove" title="Stop monitoring" onclick="patchMonitor(${x.id},false)">📡</button>`}</article>`}).join('');monitoredReleaseList.innerHTML=rows.length?`<div class="downloadTable monitoredTable"><div class="downloadTableHead"><label class="check compact monitoredRowSelect" title="Select all on this page"><input type="checkbox" ${rows.length&&rows.every(x=>monitoredSelected.has(x.id))?'checked':''} onchange="toggleMonitoredSelectAll(this.checked)"></label><span>Release</span><span>Release date</span><span>Site / flags</span><span>Added / updated</span><span>Status</span><span></span></div>${body}</div>`:'<div class="empty">No releases are actively monitored. Use 📡 Monitor on a release card or choose “All missing and future releases” on a site.</div>';renderMonitoredPagination(total,limit);monitoredVisibleIDs=rows.map(x=>x.id);renderMonitoredBulkBar()}catch(e){monitoredReleaseCount.textContent='Unavailable';monitoredReleaseList.innerHTML=`<div class="empty">${esc(e.message)}</div>`;monitoredPagination.innerHTML=''}}
async function pollDownloadSearch(){try{const j=await api('/jobs/download-search');downloadSearchStatus.textContent=j.running?`Running · checking ${j.video_id||'…'} · ${j.checked} checked`:`${settings.download_search_enabled==='true'?'Enabled':'Disabled'} · every ${settings.download_search_interval||'1h'} · last run: ${j.finished_at?new Date(j.finished_at).toLocaleString():'never'} · ${j.downloaded||0} downloading, ${j.skipped||0} skipped${j.failed?' · '+j.failed+' failed':''}`;runDownloadSearch.disabled=!!j.running;if(j.running)setTimeout(pollDownloadSearch,1000);else loadDownloads()}catch(e){downloadSearchStatus.textContent=e.message}}
async function pollDownloadSearchOlder(){try{const j=await api('/jobs/download-search-older');downloadSearchOlderStatus.textContent=j.running?`Running · checking ${j.video_id||'…'} · ${j.checked} checked`:`${settings.download_search_older_enabled==='true'?'Enabled':'Disabled'} · every ${settings.download_search_older_interval||'24h'} · older than ${settings.monitor_older_days||'30'}d · last run: ${j.finished_at?new Date(j.finished_at).toLocaleString():'never'} · ${j.downloaded||0} downloading, ${j.skipped||0} skipped${j.failed?' · '+j.failed+' failed':''}`;runDownloadSearchOlder.disabled=!!j.running;if(j.running)setTimeout(pollDownloadSearchOlder,1000);else loadDownloads()}catch(e){downloadSearchOlderStatus.textContent=e.message}}
async function pollCoverCache(){try{const j=await api('/jobs/covers');coverCacheProgress.max=Math.max(j.total||1,1);coverCacheProgress.value=j.checked||0;cacheAllCovers.disabled=!!j.running;coverCacheStatus.textContent=j.running?`Caching ${j.video_id||'…'} · ${j.checked}/${j.total} checked · ${j.cached} downloaded · ${j.skipped} already cached · ${j.failed} failed`:`${j.finished_at?'Last completed '+new Date(j.finished_at).toLocaleString():'Not run yet'} · ${j.checked||0}/${j.total||0} checked · ${j.cached||0} downloaded · ${j.skipped||0} already cached · ${j.failed||0} failed${j.last_error?' · Last error: '+j.last_error:''}`;if(j.running)setTimeout(pollCoverCache,1000)}catch(e){coverCacheStatus.textContent=e.message}}
function notificationFilterValues(){let values=[];for(const n of notificationRows){const x=n.release;if(!x)continue;if(prefs.notificationCategory==='Actress')values.push(...actressValues(x));if(prefs.notificationCategory==='Tag')values.push(...tagValues(x));if(prefs.notificationCategory==='Studio')values.push(x.studio);if(prefs.notificationCategory==='Label')values.push(...labelValues(x))}if(prefs.notificationCategory==='Actress')values=values.flatMap(v=>[v,reversedName(v)]);return [...new Set(values.map(v=>String(v||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}))}
function populateNotificationEntries(){const values=notificationFilterValues();notificationEntryOptions.innerHTML=values.map(v=>`<option value="${attr(v)}"></option>`).join('');notificationEntry.value=prefs.notificationEntry||''}
function filteredNotifications(){const query=(prefs.notificationSearch||'').trim().toLowerCase(),entry=prefs.notificationEntry;const rows=notificationRows.filter(n=>{const x=n.release;if(!x)return false;const generalText=[x.video_id,x.title,x.studio,...labelValues(x),...tagValues(x)].join(' ').toLowerCase();if(query&&!generalText.includes(query)&&!actressValues(x).some(v=>actressMatch(v,query)))return false;if(prefs.notificationStatus==='released'&&!x.released)return false;if(prefs.notificationStatus==='upcoming'&&x.released)return false;if(prefs.notificationStatus==='local'&&!x.local)return false;if(prefs.notificationStatus==='desired'&&!x.desired)return false;if(entry){if(prefs.notificationCategory==='Actress'&&!actressValues(x).some(v=>actressMatch(v,entry)))return false;if(prefs.notificationCategory==='Tag'&&!tagValues(x).some(v=>wildcardMatch(v,entry)))return false;if(prefs.notificationCategory==='Studio'&&!wildcardMatch(x.studio,entry))return false;if(prefs.notificationCategory==='Label'&&!labelValues(x).some(v=>wildcardMatch(v,entry)))return false}return true});return rows.sort((a,b)=>{const ax=a.release,bx=b.release;if(prefs.notificationSort==='name')return ax.title.localeCompare(bx.title);if(prefs.notificationSort==='id')return ax.video_id.localeCompare(bx.video_id);if(prefs.notificationSort==='release')return String(bx.release_date).localeCompare(String(ax.release_date));return new Date(b.created_at)-new Date(a.created_at)})}
function renderNotifications(){populateNotificationEntries();const rows=filteredNotifications(),localTab=notificationType==='local_available';for(const id of [...notificationSelection])if(!notificationRows.some(n=>n.id===id))notificationSelection.delete(id);const limit=Number(notificationPageSize.value)||25,pages=Math.max(1,Math.ceil(rows.length/limit));if(notificationPage>pages-1)notificationPage=Math.max(0,pages-1);const pageRows=rows.slice(notificationPage*limit,notificationPage*limit+limit);notificationList.innerHTML=pageRows.map(n=>{const x=n.release;return `<article class="notificationItem ${notificationSelection.has(n.id)?'selected':''}"><label class="notificationCheck"><input type="checkbox" ${notificationSelection.has(n.id)?'checked':''} onchange="toggleNotification(${n.id},this.checked)"></label><a class="notificationCover" href="/release/${x.id}" onclick="if(!event.ctrlKey&&!event.metaKey&&!event.shiftKey){event.preventDefault();openRelease(${x.id})}"><img src="/covers/${x.id}" alt="${esc(x.video_id)}"></a><div class="notificationInfo"><div class="meta"><b>${esc(x.video_id)}</b><span>${esc(x.release_date||'Date unknown')}</span></div><h3>${esc(x.title)}</h3><small>${esc(actressValues(x).join(' · ')||x.studio||'')}</small><div class="notificationTags">${tagValues(x).slice(0,5).map(t=>`<span>${esc(t)}</span>`).join('')}</div></div><div class="notificationState"><b>${x.local?'● Local':x.released?'● Released':'◷ Upcoming'}</b><small>${new Date(n.created_at).toLocaleString()}</small><button onclick="clearNotification(${n.id})">✓ Clear</button></div></article>`}).join('')||'<div class="empty">No notifications match this tab and its filters.</div>';notificationSelectAll.checked=pageRows.length>0&&pageRows.every(n=>notificationSelection.has(n.id));notificationSelectAll.indeterminate=pageRows.some(n=>notificationSelection.has(n.id))&&!notificationSelectAll.checked;notificationSelected.textContent=`${notificationSelection.size} selected · ${rows.length} matching`;notificationDownload.hidden=localTab;notificationDownload.disabled=localTab||notificationSelection.size===0;notificationOpenLinks.disabled=notificationClear.disabled=notificationSelection.size===0;renderNotificationPagination(rows.length,limit)}
function renderNotificationPagination(total,limit){const pages=Math.max(1,Math.ceil(total/limit));notificationPagination.innerHTML=total?`<button ${notificationPage<=0?'disabled':''} onclick="changeNotificationPage(-1)">‹ Prev</button><span>Page ${notificationPage+1} of ${pages} · ${total} total</span><button ${notificationPage>=pages-1?'disabled':''} onclick="changeNotificationPage(1)">Next ›</button>`:''}
function changeNotificationPage(delta){notificationPage=Math.max(0,notificationPage+delta);renderNotifications()}
function toggleNotification(id,checked){if(checked)notificationSelection.add(id);else notificationSelection.delete(id);renderNotifications()}
function selectedNotifications(){return notificationRows.filter(n=>notificationSelection.has(n.id)&&n.release)}
async function loadNotifications(){try{notificationRows=await api('/notifications?type='+notificationType);notificationSelection.clear();notificationSearch.value=prefs.notificationSearch||'';notificationCategory.value=prefs.notificationCategory||'';notificationStatus.value=prefs.notificationStatus||'';notificationSort.value=prefs.notificationSort||'notification';notificationPageSize.value=prefs.notificationPageSize||25;notificationPage=0;renderNotifications()}catch(e){notificationList.innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
async function clearNotification(id){try{await api('/notifications?type='+encodeURIComponent(notificationType),{method:'DELETE',body:JSON.stringify({ids:[id]})});notificationSelection.delete(id);await loadNotifications();toast('Notification cleared')}catch(e){toast(e.message)}}
async function clearSelectedNotifications(all=false){const ids=all?[]:selectedNotifications().map(n=>n.id),label=all?'every notification in this tab':`${ids.length} selected notification${ids.length===1?'':'s'}`;if(!all&&!ids.length)return;if(!confirm(`Clear ${label}?`))return;try{const result=await api('/notifications?type='+encodeURIComponent(notificationType),{method:'DELETE',body:JSON.stringify({ids})});await loadNotifications();toast(`${result.deleted} notification${result.deleted===1?'':'s'} cleared`)}catch(e){toast(e.message)}}
async function downloadSelectedNotifications(){const selected=selectedNotifications();if(!selected.length)return;notificationDownload.disabled=true;let submitted=0,failed=0;for(let i=0;i<selected.length;i++){const release=selected[i].release;notificationSelected.textContent=`Searching ${i+1}/${selected.length} · ${release.video_id}`;try{const results=await api(`/releases/${release.id}/search`),accepted=results.find(x=>x.accepted);if(!accepted){failed++;continue}const result=await api(`/releases/${release.id}/download`,{method:'POST',body:JSON.stringify(accepted)});if(result.status==='downloading')submitted++;else failed++}catch{failed++}}renderNotifications();toast(`${submitted} submitted${failed?' · '+failed+' skipped/failed':''}`);loadDownloads()}
function sukebeiPage(videoID){try{const raw=(settings.search_url_template||'https://sukebei.nyaa.si/?f=0&c=2_0&q=<release_id>').replaceAll('<release_id>',encodeURIComponent(videoID)),url=new URL(raw);if(url.searchParams.get('page')==='rss')url.searchParams.delete('page');url.searchParams.set('q',videoID);return url.href}catch{return''}}
function openSelectedNotificationLinks(){const urls=[];for(const n of selectedNotifications()){const x=n.release;if(String(x.source).toLowerCase()==='javlibrary'&&x.product_url)urls.push(x.product_url);const sukebei=sukebeiPage(x.video_id);if(sukebei)urls.push(sukebei)}const unique=[...new Set(urls)];for(const url of unique)window.open(url,'_blank','noopener,noreferrer');toast(`Opened ${unique.length} external page${unique.length===1?'':'s'} · allow pop-ups if blocked`)}
function editSite(id){const x=sites.find(s=>s.id===id)||{id:'',title:'',type:'Actress',name:'JavLibrary',url:'',rss_url:'',notify:false,download_mode:'',desired:false,enabled:true},f=siteForm;for(const k of ['id','title','type','name','url','rss_url'])f.elements[k].value=k==='type'&&x[k]==='Genre'?'Tag':x[k]||'';f.elements.download_mode.value=x.download_mode||(x.download?'future':'');for(const k of ['notify','desired','enabled'])f.elements[k].checked=!!x[k];syncSiteURLGuidance();siteDialog.showModal()}
async function deleteSite(id){if(!confirm('Delete this site and its releases?'))return;await api('/sites/'+id,{method:'DELETE'});await loadAll();toast('Site deleted')}
function openRefresh(siteID=0,mode='quick',releaseID=0){refreshForm.elements.site_id.value=siteID;refreshForm.elements.release_id.value=releaseID;refreshForm.elements.mode.value=mode;refreshForm._syncAllPages();refreshDialog.showModal()}
async function refreshRelease(releaseID){updateProgress.removeAttribute('value');updateStatus.textContent='Queueing release detail update…';if(!updateDialog.open)updateDialog.showModal();try{const j=await api('/jobs/refresh',{method:'POST',body:JSON.stringify({release_id:releaseID,mode:'detail',kind:'update_details'})});toast(j.state==='queued'?`Release detail update queued · priority ${j.priority||5}`:'Release detail update started');pollReleaseRefresh(releaseID)}catch(e){updateProgress.value=0;updateStatus.textContent='✕ '+e.message;toast(e.message)}}

function refreshOutcomeText(j){if(j.error){if(j.outcome==='blocked')return{status:'✕ Scrape blocked: '+j.error,toast:'Release scrape blocked'};if(j.outcome==='invalid')return{status:'✕ Scrape invalid: '+j.error,toast:'Release scrape invalid'};return{status:'✕ Update failed: '+j.error,toast:'Release detail update failed'}}if(j.outcome==='no_change')return{status:'✓ No new information found',toast:'No new information found'};return{status:'✓ Metadata updated',toast:'Release details updated'}}
async function pollReleaseRefresh(releaseID){try{const j=await api(`/jobs/refresh?release_id=${releaseID}`);if(j.running){updateStatus.textContent=j.state==='queued'?`Queued at priority ${j.priority||5} · position ${j.queue_depth||1}`:`Update release details for ${j.video_id||'release'} from ${j.provider||'source'}…`;setTimeout(()=>pollReleaseRefresh(releaseID),650);return}updateProgress.value=1;const outcome=refreshOutcomeText(j);updateStatus.textContent=outcome.status;toast(outcome.toast);if(!j.error){await Promise.all([loadStats(),loadReleases()]);if(releaseDialog.open&&activeReleaseID===releaseID)renderReleaseDetail(await api('/releases/'+releaseID))}pollJob()}catch(e){updateProgress.value=0;updateStatus.textContent='✕ '+e.message;toast(e.message)}}
async function pollJob(){clearTimeout(jobPollTimer);if(jobPollBusy){jobPollTimer=setTimeout(pollJob,300);return}jobPollBusy=true;let interval=5000;try{const j=await api('/jobs/refresh'),source=esc(j.page_limit_source||(j.all_pages?'safety limit':'configured limit')),page=`page ${j.page||0}/${j.page_limit||0} · ${source}`,queue=j.queue_depth?` · ${j.queue_depth} queued`:'',queuedJobs=j.queued_jobs||[],queuedMarkup=queuedJobs.length?`<section class="queuedJobs"><header><b>Queued next</b><span>${queuedJobs.length} job${queuedJobs.length===1?'':'s'}</span></header>${queuedJobs.map(x=>`<article><strong>${x.position}</strong><div><b>${esc(x.title||'Queued scrape')}</b><small>${x.release_id?'Release details':x.scheduled?'Scheduled scrape':'Manual scrape'} · ${esc(x.mode||'quick')}${x.all_pages?' · through site end':''}</small></div><span>P${x.priority||8}</span></article>`).join('')}</section>`:'';interval=j.running?800:5000;stopScrapeJob.hidden=!j.running;stopScrapeJob.disabled=j.state==='stopping';stopScrapeJob.textContent=j.state==='stopping'?'Stopping…':'■ Stop job';jobStatus.innerHTML=j.running?`<div class="row"><b>${esc(j.state)} · ${esc(j.site_title||'All sites')}</b><span>${esc(j.mode)} · ${page}</span><small>Priority ${j.priority||8}${queue} · ${j.added||0} new · ${j.updated||0} updated · ${j.skipped||0} skipped</small></div>${queuedMarkup}`:`<p>${j.state==='cancelled'?'Last scrape job was cancelled.':'No active scrape job.'}</p>`;headerJobWidget.classList.toggle('active',!!j.running);headerJobWidget.classList.toggle('stopping',j.state==='stopping');headerJobText.textContent=!j.running?'Idle':j.state==='stopping'?'Stopping…':j.state==='queued'?`Queued${j.queue_depth?` · ${j.queue_depth}`:''}`:`Scraping · ${j.page||0}/${j.page_limit||0}`;headerJobIndicator.title=j.running?`${j.site_title||'All sites'} · ${j.mode||'scrape'} · ${page}${j.queue_depth?` · ${j.queue_depth} queued`:''}`:'No scrape job is running · open Jobs';if(lastJobRunning&&!j.running){loadStats();loadReleases();loadSites();loadJobHistory()}lastJobRunning=!!j.running}catch{headerJobText.textContent='Status unavailable';headerJobWidget.classList.remove('active','stopping');interval=5000}finally{jobPollBusy=false;jobPollTimer=setTimeout(pollJob,interval)}}
async function pollStash(){const j=await api('/jobs/stash');stashStatus.innerHTML=`<p>${j.running?'Running':j.error?'Failed':'Idle'} · ${j.matched||0} matched · ${j.updated||0} updated</p>${j.error?`<p>${esc(j.error)}</p>`:''}`;if(j.running)setTimeout(pollStash,1200)}
async function loadJobHistory(){const [rows,downloadPage]=await Promise.all([api('/jobs/history'),api('/downloads?limit=50')]);const jobs=rows.map(j=>`<div class="row"><b>${esc(j.state)}</b><span>${esc(j.kind)} ${esc(j.mode)} ${esc(j.site_title)}</span><small>${j.added} new · ${j.updated} updated · ${j.skipped} skipped${j.error?' · '+esc(j.error):''}</small></div>`);const activity=(downloadPage.items||[]).map(d=>`<div class="row"><b>${esc(d.status)}</b><span>${esc(d.source_type)} · ${esc(d.query||d.name)}</span><small>${esc(d.provider)} · ${esc(d.match_reason||d.error||'')}</small></div>`);jobHistory.innerHTML=[...jobs,...activity].join('')||'<p>No completed activity.</p>'}
const logIcons={DEBUG:'🐛',INFO:'ℹ️',WARN:'⚠️',ERROR:'❌'};
// scrapeStatusMeta clearly marks the scrape-validity events introduced in
// Phase 2 (and used for Phase 12's live per-release progress) - the
// "scrape response valid"/"scrape response rejected" log lines carry a
// status field (VALID/BLOCKED/INVALID/ERROR) that would otherwise look
// like any other INFO line.
const scrapeStatusMeta={VALID:{icon:'✅',label:'Valid'},BLOCKED:{icon:'🛡️',label:'Blocked'},INVALID:{icon:'🚫',label:'Invalid'},ERROR:{icon:'⚠️',label:'Error'}};
function renderLogs(){const box=$('#liveLog'),level=$('#logLevelFilter').value,query=$('#logTextFilter').value.trim().toLowerCase(),scrollTop=box.scrollTop;const rows=logRows.filter(x=>{const normalized=String(x.level||'INFO').toUpperCase();if(level!=='ALL'&&normalized!==level)return false;if(!query)return true;return [x.message,...Object.entries(x.fields||{}).flat()].join(' ').toLowerCase().includes(query)});box.innerHTML=rows.map(x=>{const level=String(x.level||'INFO').toUpperCase(),date=new Date(x.time),fields=Object.entries(x.fields||{}).map(([k,v])=>`<span class="logField ${k.toLowerCase()==='error'?'error':''}"><b>${esc(k)}</b>=${esc(String(v))}</span>`).join(''),scrapeStatus=(x.message==='scrape response valid'||x.message==='scrape response rejected')?String((x.fields&&x.fields.status)||'').toUpperCase():'',scrapeMeta=scrapeStatusMeta[scrapeStatus];return `<article class="logEntry" data-level="${esc(level)}" data-scrape="${esc(scrapeStatus)}"><time class="logTime" datetime="${esc(date.toISOString())}" title="${esc(date.toLocaleString())}">${esc(date.toLocaleTimeString())}</time><span class="logLevel">${logIcons[level]||'•'} ${esc(level)}</span><div class="logMessage">${scrapeMeta?`<span class="scrapeBadge scrapeBadge-${esc(scrapeStatus)}">${scrapeMeta.icon} Scrape ${scrapeMeta.label}</span> `:''}${esc(x.message)}${fields?`<div class="logFields">${fields}</div>`:''}</div></article>`}).join('')||`<div class="logEmpty">${logRows.length?'🔎 No log entries match these filters.':'💤 No server log entries yet.'}</div>`;logSummary.textContent=`${rows.length} of ${logRows.length} loaded${logHasMoreOlder?'+':''} entries · updated ${new Date().toLocaleTimeString()}`;if(logFollow.checked)box.scrollTop=box.scrollHeight;else box.scrollTop=scrollTop}
// loadLogs is the fresh "entering the Logs view" load: the newest page,
// discarding whatever was previously accumulated (Phase 13). Incremental
// growth from there on happens via pollLogsTail (new entries) and
// loadOlderLogs (scrolling up for history) so a long-running session never
// has to re-fetch or hold its entire log history at once.
async function loadLogs(){try{const rows=await api('/logs?limit=200');logRows=rows;logOldestSeq=rows.length?rows[0].seq:0;logNewestSeq=rows.length?rows[rows.length-1].seq:0;logHasMoreOlder=rows.length===200;renderLogs()}catch(e){logSummary.textContent='Log unavailable';liveLog.innerHTML=`<div class="logEmpty">⚠️ ${esc(e.message)}</div>`}}
// loadOlderLogs extends the loaded window backward when the user scrolls
// near the top of the log box, instead of ever loading the whole history.
async function loadOlderLogs(){if(logLoadingOlder||!logHasMoreOlder||!logOldestSeq)return;logLoadingOlder=true;try{const older=await api(`/logs?before=${logOldestSeq}&limit=200`);const box=$('#liveLog'),prevHeight=box.scrollHeight;if(older.length){logRows=[...older,...logRows];logOldestSeq=older[0].seq;logHasMoreOlder=older.length===200;if(logRows.length>LOG_CLIENT_CAP){logRows=logRows.slice(0,LOG_CLIENT_CAP);logNewestSeq=logRows[logRows.length-1].seq}renderLogs();box.scrollTop=box.scrollHeight-prevHeight}else{logHasMoreOlder=false}}catch{}finally{logLoadingOlder=false}}
// pollLogsTail fetches only entries newer than what is already loaded
// (Phase 13), instead of re-fetching and replacing the whole visible
// window every tick. Growth is capped client-side (LOG_CLIENT_CAP) by
// dropping the oldest already-loaded rows, which just re-enables
// loadOlderLogs for them rather than losing them (still retained
// server-side up to the ring's own capacity).
async function pollLogsTail(){try{const fresh=await api(`/logs?after=${logNewestSeq}&limit=500`);if(!fresh.length)return;logRows=[...logRows,...fresh];logNewestSeq=fresh[fresh.length-1].seq;if(logRows.length>LOG_CLIENT_CAP){logRows=logRows.slice(logRows.length-LOG_CLIENT_CAP);logOldestSeq=logRows[0].seq;logHasMoreOlder=true}renderLogs()}catch{}}
siteForm.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),id=f.get('id'),x={title:f.get('title'),type:f.get('type'),name:f.get('name'),url:f.get('url'),rss_url:f.get('rss_url'),notify:f.has('notify'),download_mode:f.get('download_mode'),desired:f.has('desired'),enabled:f.has('enabled')};await api('/sites'+(id?'/'+id:''),{method:id?'PUT':'POST',body:JSON.stringify(x)});siteDialog.close();toast(x.download_mode==='all'?'Site saved · missing releases added to Monitoring':'Site saved');await Promise.all([loadSites(),loadMonitoredReleases()] )};
refreshForm.onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),allPages=f.has('all_pages'),priority=Number(f.get('priority'))||0;const j=await api('/jobs/refresh',{method:'POST',body:JSON.stringify({site_id:Number(f.get('site_id')),release_id:Number(f.get('release_id')),mode:f.get('mode'),pages:allPages?0:Number(f.get('pages')),all_pages:allPages,kind:'site_refresh',priority})});refreshDialog.close();toast(`Manual refresh queued · priority ${j.priority||8}`);pollJob()};
function selectJobSite(showNotice=true){const query=jobSiteSearch.value.trim();if(!query){jobSite.value='0';if(showNotice)toast('Selected all enabled sites');return true}const matches=sites.filter(x=>wildcardMatch(`${x.title} · ${x.name}`,query)||wildcardMatch(x.url,query));if(!matches.length){jobSite.value='';if(showNotice)toast(`No monitoring site matches: ${query}`);return false}const selected=matches[0];jobSite.value=selected.id;jobSiteSearch.value=`${selected.title} · ${selected.name}`;if(showNotice)toast(`Selected site: ${selected.title}`);return true}
manualScrapeForm.onsubmit=async e=>{e.preventDefault();if(!selectJobSite(false))return toast(`No monitoring site matches: ${jobSiteSearch.value}`);const f=new FormData(e.target),allPages=f.has('all_pages'),priority=Number(f.get('priority'))||0,kind=allPages?'manual_full':'start_source';try{const j=await api('/jobs/refresh',{method:'POST',body:JSON.stringify({site_id:Number(f.get('site_id')),mode:f.get('mode'),pages:allPages?0:Number(f.get('pages')),all_pages:allPages,kind,priority})});toast(`${f.get('mode')==='new'?'New-release scrape':'Manual scrape'} queued · priority ${j.priority||(allPages?20:10)}${allPages?' · through site end':''}`);pollJob()}catch(error){toast(error.message)}};
