async function loadIntegrationConfig(){const [mappings,steps]=await Promise.all([api('/path-mappings'),api('/pipeline')]);mappingList.innerHTML=mappings.map(x=>`<div class="row"><small>${esc(x.download_prefix)} → ${esc(x.local_prefix)}</small><button type="button" onclick="removeMapping(${x.id})">×</button></div>`).join('')||'<small>No path mappings.</small>';pipelineList.innerHTML='';steps.forEach(addPipelineStep);enablePipelineDrag()}
async function removeMapping(id){await api('/path-mappings/'+id,{method:'DELETE'});loadIntegrationConfig()}
function addPipelineStep(step={trigger:'download_completed',type:'shell',name:'New step',config:{command:'',output_path:''},enabled:true,timeout_seconds:0}){const n=document.createElement('div');n.className='row pipelineStep';n.draggable=true;const config=typeof step.config==='string'?step.config:JSON.stringify(step.config||{});n.innerHTML=`<span title="Drag to reorder">⠿</span><div><input class="stepName" value="${esc(step.name)}" aria-label="Step name"><div class="pipelineStepMeta"><label>Event<select class="stepTrigger"><option value="download_completed">Download completed successfully</option><option value="download_completed_removed">Download successfully removed</option></select></label><label>Action<select class="stepType"><option value="shell">Shell / file move</option><option value="stash_graphql">StashApp GraphQL</option></select></label><label class="check"><input class="stepEnabled" type="checkbox" ${step.enabled!==false?'checked':''}> Enabled</label><label title="How long this step may run before it is treated as failed. Leave at 0 to use the default step timeout from Settings.">Timeout (s)<input class="stepTimeout" type="number" min="0" step="1" value="${Number(step.timeout_seconds)||0}" placeholder="Default"></label></div><textarea class="stepConfig" rows="4" aria-label="Step JSON configuration">${esc(config)}</textarea><div class="stepTestRow"><button type="button" class="stepTest">▶ Test step</button><span class="stepTestResult" hidden></span></div></div><button type="button" class="removeStep" title="Remove step" aria-label="Remove step">×</button>`;n.querySelector('.stepTrigger').value=step.trigger||'download_completed';n.querySelector('.stepType').value=step.type;n.querySelector('.removeStep').onclick=()=>n.remove();n.querySelector('.stepTest').onclick=()=>testPipelineStep(n);pipelineList.append(n)}
async function testPipelineStep(row){const resultEl=row.querySelector('.stepTestResult'),button=row.querySelector('.stepTest');let config;try{config=JSON.parse(row.querySelector('.stepConfig').value||'{}')}catch(e){resultEl.hidden=false;resultEl.className='stepTestResult fail';resultEl.textContent='Invalid JSON configuration: '+e.message;return}const step={trigger:row.querySelector('.stepTrigger').value,type:row.querySelector('.stepType').value,name:row.querySelector('.stepName').value,config,enabled:true,timeout_seconds:Number(row.querySelector('.stepTimeout').value)||0};button.disabled=true;button.textContent='Testing…';resultEl.hidden=false;resultEl.className='stepTestResult';resultEl.textContent='Running against sample values…';try{const x=await api('/pipeline/test',{method:'POST',body:JSON.stringify(step)});resultEl.className='stepTestResult '+(x.passed?'pass':'fail');resultEl.textContent=(x.passed?'✓ Passed':'✗ Failed'+(x.error?': '+x.error:''))+(x.output?'\n'+x.output:'')}catch(e){resultEl.className='stepTestResult fail';resultEl.textContent='✗ '+e.message}finally{button.disabled=false;button.textContent='▶ Test step'}}
function enablePipelineDrag(){let dragging;pipelineList.ondragstart=e=>{dragging=e.target.closest('.pipelineStep')};pipelineList.ondragover=e=>{e.preventDefault();const over=e.target.closest('.pipelineStep');if(over&&over!==dragging){const box=over.getBoundingClientRect();pipelineList.insertBefore(dragging,e.clientY<box.top+box.height/2?over:over.nextSibling)}}}
